"""
generate_documentation_tables.py
Generates clean standalone Markdown and CSV tables for the Use Case Documentation Suite.
Target: docs/use-case-documentation/tables/
"""

import os
import csv

TABLES_DIR = os.path.join(os.path.dirname(__file__), "..", "docs", "use-case-documentation", "tables")
os.makedirs(TABLES_DIR, exist_ok=True)

def write_table_files(base_name, headers, rows):
    # Write CSV
    csv_path = os.path.join(TABLES_DIR, f"{base_name}.csv")
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(headers)
        writer.writerows(rows)
    print(f"Generated CSV: {csv_path}")

    # Write Markdown
    md_path = os.path.join(TABLES_DIR, f"{base_name}.md")
    with open(md_path, "w", encoding="utf-8") as f:
        f.write(f"# Table: {base_name.replace('-', ' ').title()}\n\n")
        header_line = "| " + " | ".join(headers) + " |"
        separator_line = "| " + " | ".join(["---"] * len(headers)) + " |"
        f.write(header_line + "\n")
        f.write(separator_line + "\n")
        for r in rows:
            clean_cells = [str(c).replace("|", "\\|").replace("\n", " ") for c in r]
            f.write("| " + " | ".join(clean_cells) + " |\n")
        f.write("\n")
    print(f"Generated Markdown: {md_path}")

